  have result := LeanExperiments.RunningMedian.rebalanceUpper lower upper;
  result.2.size ≤ result.1.size + 1

LeanExperiments.Verification.HeapSort.Sp.type:
∀ (input : Array ℕ),
  input.size = 9 →
    (have stage3 := LeanExperiments.HeapSort.siftDownRecursive input 3;
      have stage2 := LeanExperiments.HeapSort.siftDownRecursive stage3 2;
      have stage1 := LeanExperiments.HeapSort.siftDownRecursive stage2 1;
      stage1[1]! ≤ stage1[0]! ∧ stage1[2]! ≤ stage1[0]!) →
      LeanExperiments.Verification.Sorting.Spec.Correct input.toList
        (LeanExperiments.HeapSort.heapSortRecursive input).toList

LeanExperiments.Verification.MergeSort.m.type:
∀ (left right emitted : List ℕ),
  LeanExperiments.Verification.MergeSort.mergeLoopRun left right emitted =
    match left, right with
    | [], x => { leftRemaining := left, rightRemaining := right, emitted := emitted }
    | x, [] => { leftRemaining := left, rightRemaining := right, emitted := emitted }
    | leftHead :: leftTail, rightHead :: rightTail =>
      if leftHead ≤ rightHead then
        LeanExperiments.Verification.MergeSort.mergeLoopRun leftTail (rightHead :: rightTail) (emitted ++ [leftHead])
      else LeanExperiments.Verification.MergeSort.mergeLoopRun (leftHead :: leftTail) rightTail (emitted ++ [rightHead])

LeanExperiments.Verification.HeapSort.Sp.type:
∀ (root left right leftLeft leftRight rightLeft rightRight leftLeftLeft leftLeftRight : ℕ),
  have values := #[root, left, right, leftLeft, leftRight, rightLeft, rightRight, leftLeftLeft, leftLeftRight];
  have stage3 := LeanExperiments.HeapSort.siftDownRecursive values 3;
  have stage2 := LeanExperiments.HeapSort.siftDownRecursive stage3 2;
  have stage1 := LeanExperiments.HeapSort.siftDownRecursive stage2 1;
  stage1[3]! ≤ stage1[1]! ∧
    stage1[4]! ≤ stage1[1]! ∧
      stage1[7]! ≤ stage1[3]! ∧ stage1[8]! ≤ stage1[3]! ∧ stage1[5]! ≤ stage1[2]! ∧ stage1[6]! ≤ stage1[2]!

LeanExperiments.Verification.RunningMedi.type:
∀ (lower upper : Array ℕ),
  have lowerResult := LeanExperiments.RunningMedian.rebalanceLower lower upper;
  have result := LeanExperiments.RunningMedian.rebalanceUpper lowerResult.1 lowerResult.2;
  (result.1.toList ++ result.2.toList).Perm (lower.toList ++ upper.toList)

∀ (lower upper : Array ℕ),
